    fn notice(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> String {
        view.read_with(cx, |v, _| v.model.as_ref().unwrap().notice.clone())
    }

    /// Why the yard did not take the ask's answer, as its card says it,
    /// or nothing where the card says nothing.
    fn refused_of(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
        bead: &str,
        ask: u64,
    ) -> String {
        view.read_with(cx, |v, _| {
            v.refused
                .get(&(bead.to_string(), ask))
                .cloned()
                .unwrap_or_default()
        })
    }

    /// The hash of the image open over the window, if one is. The
    /// window's debug bounds only ever gain selectors, so what shuts is
    /// said here, not by a selector going missing.
    fn overlay_image(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Option<String> {
        view.read_with(cx, |v, _| {
            v.image_open.as_ref().map(|open| open.hash.clone())
        })
    }

    /// Whether the line has the keys.
    fn line_focused(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> bool {
        cx.update(|window, cx| view.read(cx).line.focus_handle(cx).is_focused(window))
    }

    /// What the window has of the image `hash`: `here`, `asked`, the line
    /// that says why there is none, or nothing.
    fn picture(view: &Entity<Footplate>, cx: &mut VisualTestContext, hash: &str) -> String {
        view.read_with(cx, |v, _| match v.images.get(hash) {
            Some(Picture::Here(_)) => "here".to_string(),
            Some(Picture::Asked) => "asked".to_string(),
            Some(Picture::Not(why)) => why.clone(),
            None => String::new(),
        })
    }

    /// What is attached to the draft of the open conversation: for each
    /// its id, its name and why it is marked.
    fn attached(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> Vec<(u64, String, Option<String>)> {
        view.read_with(cx, |v, _| {
            let with = v.model.as_ref().unwrap().selected_conversation().unwrap();
            let all = v.drafts.attachments(with).iter();
            all.map(|a| (a.id, a.name.clone(), a.refused.clone()))
                .collect()
        })
    }

    /// What is attached to the ask's note on the open card: for each its
    /// id, its name and why it is marked.
    fn card_attached(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
        bead: &str,
        ask: u64,
    ) -> Vec<(u64, String, Option<String>)> {
        view.read_with(cx, |v, _| {
            v.card_files(bead, ask)
                .iter()
                .map(|a| (a.id, a.name.clone(), a.refused.clone()))
                .collect()
        })
    }

