        yard.converse(
            "yard",
            vec![
                json!({"seq": 30, "at": "2026-10-08T09:31:00Z", "from": "yard", "to": "jo", "text": "not delivered: rate_limited", "read": true}),
            ],
        );
        mails(&yard, &["Hello."]);
