    #[gpui::test]
    fn a_correction_carries_its_label_and_the_header_names_the_state(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        mails(
            &yard,
            &["the grant is ready", "correction the grant is not ready"],
        );
        // The label says the word, so the text under it starts after it;
        // the plain mail's text is as it was written.
        let (view, cx) = opened(&yard, &["the grant is ready", "the grant is not ready"], cx);
        // The correction carries its label above its text; the plain mail
        // carries none.
        assert!(!drawn(cx, "correction 12"));
        assert!(drawn(cx, "correction 13"));
        // What is drawn under the label is what a drag over it selects: the
        // text from its first letter to its last.
        let said = "the grant is not ready";
        let (from, to) = (
            place(cx, 13, said, 0, 1.),
            place(cx, 13, said, said.len(), -1.),
        );
        drag(cx, from, to);
        assert_eq!(selected(&view, cx).as_deref(), Some(said));
        // The yardmaster idles in jo's yard: the header says so beside
        // the name.
        assert!(drawn(cx, "conversation state"));
    }

    /// A crew member whose session sits at its harness's login screen is
    /// not logged in, whatever its runtime reads the screen as: its row and
    /// the header say so, its dot waits, and the line under the user's mail
    /// to it says it cannot read it. The yard raises `crew_login` when the
    /// login changes, so the crew is read again, and the words go when the
    /// screen does.
    #[gpui::test]
    fn a_crew_member_at_its_login_screen_is_not_logged_in_and_the_mail_to_it_says_so(
        cx: &mut TestAppContext,
    ) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let crew = |login: &str| {
            format!(
                r#"{{"result": [{{"name": "assembly", "enabled": true, "state": "stopped"}},
                    {{"name": "yardmaster", "enabled": true, "state": "running", "status": "idle", {login}}}]}}"#
            )
        };
        let screen = r#""login_screen": true"#;
        let led = r#""login_screen": true, "login_led": true"#;
        yard.answer("Crew", &crew(screen));
        yard.converse(
            "yardmaster",
            vec![
                json!({"seq": 12, "at": mailed(0), "from": "jo", "to": "yardmaster",
                "text": "hi", "read": false}),
            ],
        );
        let (view, cx) = opened(&yard, &["hi"], cx);
        // The state, the line under the mail and the dot of the row.
        let stands = |view: &Entity<Footplate>, cx: &mut VisualTestContext| {
            view.read_with(cx, |v, _| {
                let model = v.model.as_ref().unwrap();
                (
                    model.crew_state("yardmaster"),
                    model.entries()[0].standing.clone(),
                    model.crew_rows()[1].dot,
                )
            })
        };
        assert_eq!(
            stands(&view, cx),
            (
                Some("not logged in"),
                Some("yardmaster is not logged in and cannot read mail".to_string()),
                Some(model::Dot::Blocked)
            )
        );

        // The yard leads the login: its event says so, the crew is read
        // again, and the words are the yard's.
        yard.answer("Crew", &crew(led));
        yard.emit(r#"{"seq": 21, "kind": "crew_login", "actor": "yard", "at": "2026-10-08T09:31:00Z", "data": {"crew": "yardmaster", "login_screen": true, "login_led": true}}"#);
        wait(cx, "the yard's words for the login", |cx| {
            stands(&view, cx).1.is_some_and(|line| {
                line.ends_with(
                    "the yard leads its login, and waits for the operator at its asks (yardr asks)",
                )
            })
        });

        // Logged in: the session starts again with the screen gone, idle as before.
        yard.answer(
            "Crew",
            &crew(r#""login_screen": false, "login_led": false"#),
        );
        yard.emit(r#"{"seq": 22, "kind": "crew_started", "actor": "yard", "at": "2026-10-08T09:32:00Z", "data": {"crew": "yardmaster"}}"#);
        wait(cx, "the crew member idle again", |cx| {
            stands(&view, cx)
                == (
                    Some("idle"),
                    Some("sent; yardmaster is idle".to_string()),
                    Some(model::Dot::Idle),
                )
        });
    }

