    /// No name on the panel is cut at any text size: each depot, flow
    /// line and backlog count stands whole on its track's name row, and
    /// each stage head stands whole on one line or wraps whole onto a
    /// second, never truncated. The cells are in rems, so they grow with
    /// the text as the words do; in pixels they cut the words at the
    /// larger sizes.
    #[gpui::test]
    fn the_panel_holds_this_yard_s_longest_names_at_every_text_size(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_this_yard());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        wait(cx, "the panel", |cx| {
            drawn(cx, "panel track yardr yardr.train")
        });
        for text in [settings::TEXT_MIN, settings::TEXT, settings::TEXT_MAX] {
            view.update(cx, |v, cx| {
                let set = Settings {
                    text,
                    ..v.settings.clone()
                };
                v.set(set, cx)
            });
            let rem = f32::from(settings_of(&view, cx).rem());
            // One frame, read whole: a redraw per name would draw this
            // many-tracked window hundreds of times.
            drawn(cx, "panel");
            // The small words are three quarters of a rem. The depot's
            // name is seven eighths of one, and bold, which DejaVu draws
            // about a seventh wider than its regular: held at that size
            // and a seventh more.
            let small = 0.75 * rem;
            let bold = 0.875 * rem * 8. / 7.;
            for (depot, flows) in &this_yard() {
                for flow in flows {
                    let (name, flow_type) = (&flow.name, &flow.flow_type);
                    let line = match flow_type.is_empty() {
                        true => name.to_string(),
                        false => format!("{name} · {flow_type}"),
                    };
                    let backlogged = flow
                        .stages
                        .iter()
                        .filter(|(stage, ..)| stage == "backlog")
                        .count();
                    let backlog = format!("{backlogged} backlog");
                    // The name's words stand on one line each: a wrapped
                    // word would be two lines high. They hug their text,
                    // so the test platform's wide font sizes their boxes,
                    // and holding those against DejaVu says nothing; the
                    // row is held instead, as DejaVu draws it, against
                    // the card it stands in.
                    for part in ["depot", "flow", "backlog"] {
                        let at = bounds_now(cx, &format!("panel name {depot} {name} {part}"));
                        assert!(
                            f32::from(at.size.height) < rem * 1.5,
                            "at {text} px the {part} is wrapped in {depot} {name}: {at:?}"
                        );
                    }
                    let card = bounds_now(cx, &format!("panel track {depot} {name}"));
                    let available = f32::from(card.size.width) - 1.5 * rem - 2.;
                    let wide = dejavu_width(depot, bold)
                        + dejavu_width(&line, small)
                        + dejavu_width(&backlog, small)
                        + rem;
                    assert!(
                        wide <= available,
                        "at {text} px the name overflows its card in {depot} {name}: {wide} wide in {card:?}"
                    );
                    for (stage, human, _) in
                        flow.stages.iter().filter(|(stage, ..)| stage != "backlog")
                    {
                        // A head stands on one line or wraps whole onto
                        // a second, never more and never cut.
                        let head = bounds_now(cx, &format!("panel head {depot} {name} {stage}"));
                        assert!(
                            f32::from(head.size.height) < rem * 2.5,
                            "at {text} px the head wraps past two lines in {depot} {name} {stage}: {head:?}"
                        );
                        // At the largest text this yard's longest heads
                        // wrap: a truncated head would stand one line
                        // high with its words past its box.
                        if text == settings::TEXT_MAX
                            && (matches!(stage.as_str(), "contributor" | "review-security")
                                || (*human && stage == "approved"))
                        {
                            assert!(
                                f32::from(head.size.height) > rem * 1.5,
                                "at {text} px the longest head stands one line high, truncated, in {depot} {name} {stage}: {head:?}"
                            );
                        }
                    }
                }
            }
        }
    }

    /// No word of the line view or the departures board is cut at any
    /// text size: each column's head stands whole on one line, each
    /// group wraps whole onto a second line at most, and the board's
    /// platform, line and expected stand whole in their cells, while
    /// titles and remarks truncate to one line as designed. The columns
    /// are in rems with their usual widths as the floor, so they grow
    /// with the text as the words do; in pixels they cut the words at
    /// the larger sizes.
    #[gpui::test]
    fn the_line_view_and_the_board_hold_their_words_at_every_text_size(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_longest());
        yard.answer("Flows", &flows_this_yard());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        cx.run_until_parked();
        // The served stages, each read as the window reads it, so the
        // group words held are the window's own.
        let served: Value = serde_json::from_str(&flows_this_yard()).unwrap();
        for text in [settings::TEXT_MIN, settings::TEXT, settings::TEXT_MAX] {
            view.update(cx, |v, cx| {
                let set = Settings {
                    text,
                    ..v.settings.clone()
                };
                v.set(set, cx)
            });
            let rem = f32::from(settings_of(&view, cx).rem());
            // The board's words stand at seven eighths of a rem, the
            // expected arrival at three quarters in mono.
            let sm = 0.875 * rem;
            // The longest platform, line and expected stand whole in
            // their cells, as DejaVu draws them; the overlong title and
            // remark truncate to one line, and every row stands one
            // line high.
            view.update_in(cx, |v, window, cx| {
                v.select(Selected::Arrivals, window, cx);
                v.set_departures(true, cx);
            });
            wait(cx, "the board", |cx| drawn(cx, "arrival yd-hosted"));
            // One frame, read whole: a redraw per cell would draw the
            // board dozens of times.
            drawn(cx, "departures head");
            for (bead, platform, line, expected) in [
                ("yd-hosted", "review-security", "yardr-hosted", "20m–35m"),
                ("yd-design", "new", "yardr-design", "—"),
            ] {
                let row = bounds_now(cx, &format!("arrival {bead}"));
                assert!(
                    f32::from(row.size.height) < rem * 2.5,
                    "at {text} px the {bead} row wraps to two lines: {row:?}"
                );
                for (part, words) in [("platform", platform), ("line", line)] {
                    let cell = bounds_now(cx, &format!("arrival {part} {bead}"));
                    assert!(
                        f32::from(cell.size.height) < rem * 1.6,
                        "at {text} px the {part} wraps in {bead}: {cell:?}"
                    );
                    let wide = dejavu_width(words, sm);
                    assert!(
                        wide <= f32::from(cell.size.width),
                        "at {text} px the {part} overflows its cell in {bead}: {wide} wide in {cell:?}"
                    );
                }
                // The expected arrival stands in mono: no face
                // footplate meets advances past 0.65 em, so that width
                // per character holds it.
                let cell = bounds_now(cx, &format!("arrival expected {bead}"));
                let wide = 0.65 * (expected.chars().count() as f32) * 0.75 * rem;
                assert!(
                    wide <= f32::from(cell.size.width),
                    "at {text} px the expected overflows its cell in {bead}: {wide} wide in {cell:?}"
                );
            }
            for part in ["title", "remark"] {
                let cell = bounds_now(cx, &format!("arrival {part} yd-hosted"));
                assert!(
                    f32::from(cell.size.height) < rem * 1.6,
                    "at {text} px the overlong {part} wraps: {cell:?}"
                );
            }
            // Every line: each column's head stands whole on one line,
            // as DejaVu draws it bold with the lamp beside it, and each
            // group wraps whole onto a second line at most. The test
            // platform's wide font wraps the longest groups onto three
            // lines, where DejaVu wraps two, so the wrap is held as
            // DejaVu draws it against the column; the window only says
            // the groups wrap, sanely.
            for depot in served["result"]["depots"].as_array().unwrap() {
                let name = depot["name"].as_str().unwrap();
                view.update_in(cx, |v, window, cx| {
                    v.select(Selected::Line(name.to_string()), window, cx)
                });
                wait(cx, "the line", |cx| drawn(cx, &format!("flow head {name}")));
                drawn(cx, &format!("flow head {name}"));
                for flow in depot["flows"].as_array().unwrap() {
                    let flow_name = flow["name"].as_str().unwrap();
                    for stage_json in flow["stages"].as_array().unwrap() {
                        let stage: FlowStage = serde_json::from_value(stage_json.clone()).unwrap();
                        let stage_name = stage.stage.as_str();
                        let (column, head, group) = match stage_name {
                            "backlog" => (
                                format!("column {flow_name} backlog"),
                                format!("column {flow_name} backlog head"),
                                format!("column {flow_name} backlog group"),
                            ),
                            _ => (
                                format!("column {flow_name} {stage_name}"),
                                format!("column {flow_name} {stage_name} head"),
                                format!("column {flow_name} {stage_name} group"),
                            ),
                        };
                        let column = bounds_now(cx, &column);
                        // The column's padding with its border, which
                        // stand out of the words' room.
                        let available = f32::from(column.size.width) - rem - 1.;
                        // The head stands on one line, and DejaVu draws
                        // it with the lamp and its gap beside it inside
                        // the column: the lamp is half a rem, the gap a
                        // quarter, and the semibold head is held a
                        // seventh wider than its regular, as the
                        // panel's names are.
                        let head = bounds_now(cx, &head);
                        assert!(
                            f32::from(head.size.height) < rem * 1.6,
                            "at {text} px the head wraps in {name} {flow_name} {stage_name}: {head:?}"
                        );
                        let wide = dejavu_width(stage_name, sm) * 8. / 7. + 0.75 * rem;
                        assert!(
                            wide <= available,
                            "at {text} px the head overflows its column in {name} {flow_name} {stage_name}: {wide} wide in {column:?}"
                        );
                        // A terminal stage shows its stop, not words.
                        if stage.terminal {
                            continue;
                        }
                        let words = stage_group_words(&stage);
                        let group = bounds_now(cx, &group);
                        assert!(
                            rem * 1.5 < f32::from(group.size.height),
                            "at {text} px the group stands one line high, truncated, in {name} {flow_name} {stage_name}: {group:?}"
                        );
                        assert!(
                            f32::from(group.size.height) < rem * 4.2,
                            "at {text} px the group wraps past three lines in {name} {flow_name} {stage_name}: {group:?}"
                        );
                        let (lines, widest) = dejavu_lines(&words, 0.75 * rem, available);
                        assert!(
                            widest <= available,
                            "at {text} px a group word is cut in {name} {flow_name} {stage_name}: {words:?}"
                        );
                        assert!(
                            lines <= 2,
                            "at {text} px the group wraps past two lines in {name} {flow_name} {stage_name}: {words:?}"
                        );
                    }
                }
            }
        }
    }

    /// Every flow's rules stand level where groups wrap: a column whose
    /// group stands on three lines puts its rule where a column of one
    /// line does, and a terminal column with them. Each head reserves
    /// three group lines with its words on the rule, bottom-aligned.
    #[gpui::test]
    fn the_line_view_s_rules_stand_level_with_wrapped_groups(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_mixed_groups());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        cx.run_until_parked();
        let served: Value = serde_json::from_str(&flows_mixed_groups()).unwrap();
        let long_stage: FlowStage =
            serde_json::from_value(served["result"]["depots"][0]["flows"][0]["stages"][1].clone())
                .unwrap();
        let long_group = stage_group_words(&long_stage);
        for text in [settings::TEXT_MIN, settings::TEXT, settings::TEXT_MAX] {
            view.update(cx, |v, cx| {
                let set = Settings {
                    text,
                    ..v.settings.clone()
                };
                v.set(set, cx)
            });
            let rem = f32::from(settings_of(&view, cx).rem());
            view.update_in(cx, |v, window, cx| {
                v.select(Selected::Line("yardr".to_string()), window, cx)
            });
            wait(cx, "the line", |cx| drawn(cx, "flow head yardr"));
            drawn(cx, "flow head yardr");
            // The rules stand level: the backlog's, the stages', and
            // the terminal's, a wrapped group beside single-line ones.
            let mut low = f32::MAX;
            let mut high = f32::MIN;
            for rule in [
                "column default backlog rule",
                "column default new rule",
                "column default review rule",
                "column default decide rule",
                "column default approved rule",
            ] {
                let top = f32::from(bounds_now(cx, rule).top());
                low = low.min(top);
                high = high.max(top);
            }
            assert!(
                high - low < 1.,
                "at {text} px the rules stand off level between {low} and {high}"
            );
            // DejaVu draws the long group on two lines at the smallest
            // size and three at the usual and largest; the window keeps
            // the whole group and leaves every rule level even there.
            let column = bounds_now(cx, "column default new");
            let available = f32::from(column.size.width) - rem - 1.;
            let (lines, widest) = dejavu_lines(&long_group, 0.75 * rem, available);
            let want = if text == settings::TEXT_MIN { 2 } else { 3 };
            assert_eq!(
                lines, want,
                "at {text} px the long group should use {want} DejaVu lines: {long_group:?}"
            );
            assert!(
                widest <= available,
                "at {text} px a word is cut from the long group: {long_group:?}"
            );
            let wrapped = bounds_now(cx, "column default new group");
            assert!(
                rem * 1.5 < f32::from(wrapped.size.height),
                "at {text} px the long group is truncated to one line: {wrapped:?}"
            );
            assert!(
                f32::from(wrapped.size.height) < rem * 4.2,
                "at {text} px the long group wraps past three lines: {wrapped:?}"
            );
            let single = bounds_now(cx, "column default review group");
            assert!(
                f32::from(single.size.height) < rem * 1.5,
                "at {text} px the short group wraps: {single:?}"
            );
            // Every head's words stand on its rule: the padding below
            // the head alone between them, bottom-aligned.
            for (group, rule) in [
                (
                    "column default backlog group",
                    "column default backlog rule",
                ),
                ("column default new group", "column default new rule"),
                ("column default review group", "column default review rule"),
                ("column default decide group", "column default decide rule"),
            ] {
                let words = bounds_now(cx, group);
                let rule = bounds_now(cx, rule);
                let gap = f32::from(rule.top() - words.bottom());
                assert!(
                    (gap - rem * 0.25).abs() < 1.,
                    "at {text} px the head stands off its rule: {gap} in {words:?} {rule:?}"
                );
            }
        }
    }

    /// Scrolls `delta` where `selector` stands, as the wheel does,
    /// and draws the frame after it.
    fn scroll_on(cx: &mut VisualTestContext, selector: &str, delta: gpui::Point<gpui::Pixels>) {
        let position = bounds_now(cx, selector).center();
        cx.simulate_event(gpui::ScrollWheelEvent {
            position,
            delta: gpui::ScrollDelta::Pixels(delta),
            modifiers: gpui::Modifiers::default(),
            touch_phase: gpui::TouchPhase::default(),
        });
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
    }

    /// Where the line view's list stands: its offset, read from the
    /// handle the list tracks.
    fn line_offset_of(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> gpui::Point<gpui::Pixels> {
        view.read_with(cx, |v, _| v.decision.offset())
    }

    /// Stands the line view's list back at its top and draws the frame
    /// after it, so each scroll of the test starts from the top.
    fn line_top(view: &Entity<Footplate>, cx: &mut VisualTestContext) {
        view.read_with(cx, |v, _| {
            v.decision.set_offset(gpui::point(px(0.), px(0.)))
        });
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
    }

    /// Where one flow's columns stand sideways: the left edge of one of
    /// its columns. The columns hold their offset in gpui's element
    /// state, which no handle reads, so the test reads where a column
    /// stands instead.
    fn columns_left_of(cx: &mut VisualTestContext, column: &str) -> Pixels {
        bounds_now(cx, column).left()
    }

    /// A scroll moves the line view along the axis it was given, never
    /// diagonally: a vertical wheel move over a flow's columns, its
    /// head or its backlog scrolls the list and leaves every flow's
    /// columns where they stand, and a horizontal one scrolls only the
    /// columns under the pointer, leaving the list where it stands.
    /// Over a flow's head a horizontal move meets no columns, so
    /// nothing moves.
    #[gpui::test]
    fn a_scroll_moves_the_line_view_along_its_axis(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_this_yard());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        cx.run_until_parked();
        view.update_in(cx, |v, window, cx| {
            v.select(Selected::Line("footplate".to_string()), window, cx)
        });
        wait(cx, "the line", |cx| drawn(cx, "flow head footplate"));
        // A window the board stands wider and taller than: the depot's
        // eight columns against the pane, its four flows against the
        // window's height.
        cx.simulate_resize(gpui::size(px(1000.), px(600.)));
        drawn(cx, "flow head footplate");
        let over = view.read_with(cx, |v, _| v.decision.max_offset().height);
        assert!(over > px(120.), "the line fits its pane: {over:?}");
        // One column of every flow of the depot, to watch sideways.
        let columns = [
            "column default new",
            "column design.design draft",
            "column contributors.pr triage",
            "column type/release build",
        ];
        let left: Vec<Pixels> = columns.iter().map(|c| columns_left_of(cx, c)).collect();
        assert_eq!(line_offset_of(&view, cx).y, px(0.));
        // Down over a flow's columns scrolls the list and leaves every
        // flow's columns where they stand.
        scroll_on(cx, "column default new", gpui::point(px(0.), px(-120.)));
        assert_eq!(line_offset_of(&view, cx).y, px(-120.));
        for (column, stood) in columns.iter().zip(left.iter()) {
            assert_eq!(
                columns_left_of(cx, column),
                *stood,
                "a downward scroll moved {column} sideways"
            );
        }
        line_top(&view, cx);
        // Down over the flow's head does the same.
        scroll_on(cx, "flow default", gpui::point(px(0.), px(-120.)));
        assert_eq!(line_offset_of(&view, cx).y, px(-120.));
        for (column, stood) in columns.iter().zip(left.iter()) {
            assert_eq!(
                columns_left_of(cx, column),
                *stood,
                "a downward scroll over a head moved {column} sideways"
            );
        }
        line_top(&view, cx);
        // Down over the backlog does the same.
        scroll_on(cx, "column default backlog", gpui::point(px(0.), px(-120.)));
        assert_eq!(line_offset_of(&view, cx).y, px(-120.));
        for (column, stood) in columns.iter().zip(left.iter()) {
            assert_eq!(
                columns_left_of(cx, column),
                *stood,
                "a downward scroll over the backlog moved {column} sideways"
            );
        }
        line_top(&view, cx);
        // Right over a flow's columns scrolls that flow's columns
        // alone: the list and the other flows' columns stand where
        // they stood.
        scroll_on(cx, "column default new", gpui::point(px(-120.), px(0.)));
        assert_eq!(line_offset_of(&view, cx).y, px(0.));
        let stood = columns_left_of(cx, "column default new");
        assert!(
            stood < left[0],
            "a sideways scroll left the columns under it standing: {stood:?}"
        );
        for (column, at) in columns[1..].iter().zip(left[1..].iter()) {
            assert_eq!(
                columns_left_of(cx, column),
                *at,
                "a sideways scroll over another flow moved {column}"
            );
        }
        // Right over the flow's head meets no columns, so nothing
        // moves.
        scroll_on(cx, "flow default", gpui::point(px(-120.), px(0.)));
        assert_eq!(line_offset_of(&view, cx).y, px(0.));
        assert_eq!(columns_left_of(cx, "column default new"), stood);
        // Right over another flow's backlog scrolls that flow's columns
        // alone and leaves the list where it stands.
        scroll_on(
            cx,
            "column design.design backlog",
            gpui::point(px(-120.), px(0.)),
        );
        assert_eq!(line_offset_of(&view, cx).y, px(0.));
        assert_eq!(columns_left_of(cx, "column default new"), stood);
        let moved = columns_left_of(cx, "column design.design draft");
        assert!(
            moved < left[1],
            "a sideways scroll over the backlog left its columns standing: {moved:?}"
        );
    }

    /// At the narrowest window the arrivals panes hold: the list's row
    /// inside the column, the departures board's rows one line high in
    /// the board's column order with the rest scrolling sideways, and
    /// the bead's head and asks line inside the pane too.
    #[gpui::test]
    fn the_arrivals_panes_hold_at_the_narrowest_window(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_board());
        yard.answer("Bead", &bead_zulu());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        cx.run_until_parked();
        // The narrowest window the application opens (main.rs).
        cx.simulate_resize(gpui::size(px(616.), px(360.)));
        // The list's edge: a row past that runs past the column.
        let rows = bounds_of(cx, "rows");
        let edge = rows.right() + px(1.);
        let row = bounds_of(cx, "row arrivals");
        assert!(
            row.right() <= edge,
            "the arrivals row runs past the column: {row:?} past {rows:?}"
        );
        // The board: the head over the rows, each row one line high
        // with its cells in the board's order, the later columns past
        // the pane's edge scrolling sideways. The row stands below the
        // fold at this height, so the board is opened as a click opens
        // it, and the click itself is the wider window's test.
        view.update_in(cx, |v, window, cx| {
            v.select(Selected::Arrivals, window, cx);
            v.set_departures(true, cx);
        });
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival footplate-p512"));
        let right = px(616.);
        assert!(drawn(cx, "departures head"));
        for bead in ["yd-zulu", "yd-alpha", "footplate-p512"] {
            let row = bounds_of(cx, &format!("arrival {bead}"));
            let expected = bounds_of(cx, &format!("arrival expected {bead}"));
            let title = bounds_of(cx, &format!("arrival title {bead}"));
            let platform = bounds_of(cx, &format!("arrival platform {bead}"));
            let line = bounds_of(cx, &format!("arrival line {bead}"));
            assert!(
                expected.left() < title.left()
                    && title.left() < platform.left()
                    && platform.left() < line.left(),
                "the cells stand out of the board's order: {bead}"
            );
            for part in [&expected, &title, &platform, &line] {
                assert!(
                    part.top() >= row.top() - px(1.) && part.bottom() <= row.bottom() + px(1.),
                    "the cell stands off its row: {bead} {part:?} {row:?}"
                );
            }
            assert!(
                expected.right() <= right,
                "the expected runs past the pane: {expected:?}"
            );
            assert!(
                right < line.right(),
                "the line stands whole, and nothing scrolls: {line:?}"
            );
        }
        // The bead: its head and asks line inside the pane.
        click_on(cx, "arrival yd-zulu");
        wait(cx, "the bead", |cx| drawn(cx, "bead asks yd-zulu"));
        for selector in [
            "bead back",
            "bead title yd-zulu",
            "bead sub yd-zulu",
            "bead remark yd-zulu",
            "bead labels yd-zulu",
            "bead asks yd-zulu",
        ] {
            let part = bounds_of(cx, selector);
            assert!(
                part.right() <= right,
                "the bead runs past the pane: {selector} {part:?}"
            );
            assert!(
                part.top() >= px(0.),
                "the bead stands above the pane: {selector} {part:?}"
            );
        }
    }

    /// The rail stands 64 pixels wide on the window's far left: the
    /// open yard's chip on top, the three modes under it in order, the
    /// settings' gear at the foot. Each mode's tile carries its glyph
    /// over its label, as the gear does. A click on a mode opens it, on
    /// the chip the switcher, on the gear the settings.
    #[gpui::test]
    fn the_rail_holds_the_yard_s_chip_the_modes_and_the_foot(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the yard", |cx| {
            view.read_with(cx, |v, _| v.model.is_some())
        });
        // The narrowest window the application opens (main.rs).
        cx.simulate_resize(gpui::size(px(616.), px(360.)));
        let rail = bounds_of(cx, "rail");
        assert!(
            (rail.size.width - px(64.)).abs() < px(1.),
            "the rail is {rail:?}, not 64 wide"
        );
        // The chip, the modes in order, the gear: each under the
        // last, each within the rail. The chip is 40 a side; the tiles
        // are 52 wide, with their labels under their glyphs.
        let mut tops = Vec::new();
        for target in [
            "yard chip",
            "rail chat",
            "rail decisions",
            "rail timetable",
            "settings",
        ] {
            let at = bounds_of(cx, target);
            match target {
                "yard chip" => assert!(
                    (at.size.width - px(40.)).abs() < px(1.)
                        && (at.size.height - px(40.)).abs() < px(1.),
                    "{target} is {at:?}, not 40 a side"
                ),
                _ => {
                    assert!(
                        (at.size.width - px(52.)).abs() < px(1.),
                        "{target} is {at:?}, not 52 wide"
                    );
                    let label = bounds_of(cx, &format!("{target} label"));
                    assert!(
                        label.top() > at.top() + px(28.)
                            && label.bottom() <= at.bottom() + px(1.)
                            && at.left() <= label.left()
                            && label.right() <= at.right() + px(1.),
                        "{target}'s label stands off its tile: {label:?} {at:?}"
                    );
                }
            }
            assert!(
                rail.left() <= at.left() && at.right() <= rail.right() + px(1.),
                "{target} leaves the rail: {at:?} {rail:?}"
            );
            tops.push(at.top());
        }
        assert!(
            tops.windows(2).all(|pair| pair[0] < pair[1]),
            "the rail's targets stand out of order: {tops:?}"
        );
        // The foot stands at the rail's foot, and the modes at its top.
        let gear = bounds_of(cx, "settings");
        assert!(
            rail.bottom() - gear.bottom() < px(16.),
            "the gear stands off the rail's foot: {gear:?} {rail:?}"
        );
        let chip = bounds_of(cx, "yard chip");
        assert!(
            chip.top() - rail.top() < px(16.),
            "the chip stands off the rail's top: {chip:?} {rail:?}"
        );
        // A click on a mode opens it.
        assert_eq!(rail_mode(&view, cx), Mode::Chat);
        click_on(cx, "rail timetable");
        assert_eq!(rail_mode(&view, cx), Mode::Timetable);
        click_on(cx, "rail decisions");
        assert_eq!(rail_mode(&view, cx), Mode::Decisions);
        // The chip opens the switcher.
        click_on(cx, "yard chip");
        assert!(switching(&view, cx).is_some());
        assert!(drawn(cx, "switcher"));
        cx.simulate_keystrokes("escape");
        assert!(switching(&view, cx).is_none());
        // The gear opens the settings, and its key shuts them again.
        click_on(cx, "settings");
        assert!(settings_open(&view, cx));
        cx.simulate_keystrokes("secondary-,");
        assert!(!settings_open(&view, cx));
    }

    /// The rail's chat and decisions tiles carry what waits in the open
    /// yard: its unread mail and its open asks, each at its tile's top
    /// right. The timetable carries none.
    #[gpui::test]
    fn the_rail_s_chat_and_decisions_carry_what_waits(cx: &mut TestAppContext) {
        let yard = Yard::start();
        // Mail unread in a conversation that is not open, and one open
        // ask: the open conversation's own mail is read as shown.
        a_second_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks_words_only());
        let (view, cx) = opened(&yard, &["From the second home."], cx);
        wait(cx, "what waits in the open yard", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| {
                    let counts = Counts::of(m);
                    counts.mail == 1 && counts.decisions == 1
                })
            })
        });
        assert!(drawn(cx, "rail badge chat"));
        assert!(drawn(cx, "rail badge decisions"));
        assert!(!drawn(cx, "rail badge timetable"));
        // Each badge stands at its tile's top right, on the glyph's
        // corner.
        for mode in ["chat", "decisions"] {
            let tile = bounds_of(cx, &format!("rail {mode}"));
            let badge = bounds_of(cx, &format!("rail badge {mode}"));
            assert!(
                (badge.top() - tile.top()).abs() < px(1.)
                    && (tile.right() - badge.right()).abs() < px(1.),
                "the {mode} badge stands off its glyph's corner: {badge:?} {tile:?}"
            );
        }
    }

    /// While the yard is away the rail's glyphs carry no count: there
    /// is no model to count.
    #[gpui::test]
    fn the_rail_carries_no_count_while_the_yard_is_away(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let (view, cx) = no_yard(dir.path(), cx);
        assert!(view.read_with(cx, |v, _| v.model.is_none()));
        assert!(drawn(cx, "rail chat") && drawn(cx, "rail decisions"));
        assert!(!drawn(cx, "rail badge chat") && !drawn(cx, "rail badge decisions"));
    }

    /// A yard that answered and then went away keeps its rows as last
    /// seen, but its badges no longer imply that the counts are current.
    #[gpui::test]
    fn the_rail_carries_no_count_while_the_yard_reconnects(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_second_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks_words_only());
        let (view, cx) = opened(&yard, &["From the second home."], cx);
        wait(cx, "what waits in the open yard", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| {
                    let counts = Counts::of(m);
                    counts.mail == 1 && counts.decisions == 1
                })
            })
        });
        assert!(drawn(cx, "rail badge chat") && drawn(cx, "rail badge decisions"));

        yard.stop();
        wait(cx, "that the yard is away", |cx| {
            view.read_with(cx, |v, _| v.down.is_some())
        });
        wait(cx, "the switch read after the yard went away", |cx| {
            settled(&view, cx)
        });
        let (down, reconnecting, answers_under_adding, counts) = view.read_with(cx, |v, _| {
            (
                v.down.is_some(),
                v.reconnecting(),
                v.answers_under_adding(),
                rail_counts(
                    v.model.as_ref(),
                    v.down.is_some() && !v.answers_under_adding(),
                ),
            )
        });
        assert!(
            down && reconnecting && !answers_under_adding && counts.is_none(),
            "away state: down={down}, reconnecting={reconnecting}, answers_under_adding={answers_under_adding}"
        );
    }

    /// The rail's timetable tile carries a badge where the person's
    /// beads were added or closed since they last had Timetable open: at
    /// its tile's top right corner, as the other badges. Another
    /// person's bead lights nothing, and opening Timetable clears it.
    #[gpui::test]
    fn the_rail_s_timetable_carries_a_badge_for_the_person_s_beads(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        assert!(!drawn(cx, "rail badge timetable"));
        // Another person's bead, added: no badge. The arrivals are read
        // again for it, so their second read says it was applied.
        yard.emit(r#"{"seq": 21, "kind": "created", "actor": "yardmaster", "bead": "yd-shed", "data": {"originator": "ada"}}"#);
        wait(cx, "the other bead's arrival", |_| {
            yard.asked("Arrivals").len() >= 2
        });
        assert!(!drawn(cx, "rail badge timetable"));
        // One of the person's, added: the badge, on its tile's corner.
        yard.emit(r#"{"seq": 22, "kind": "created", "actor": "yardmaster", "bead": "yd-barn", "data": {"originator": "jo"}}"#);
        wait(cx, "the timetable's badge", |cx| {
            drawn(cx, "rail badge timetable")
        });
        let tile = bounds_of(cx, "rail timetable");
        let badge = bounds_of(cx, "rail badge timetable");
        assert!(
            (badge.top() - tile.top()).abs() < px(1.)
                && (tile.right() - badge.right()).abs() < px(1.),
            "the badge stands off its tile's corner: {badge:?} {tile:?}"
        );
        // Opening Timetable clears it, and keeps what was seen. A
        // painted element's selector stays in the test frame, so the
        // clearing is read from the model, as the reconnecting counts
        // are.
        to_timetable(&view, cx);
        wait(cx, "timetable open", |cx| {
            rail_mode(&view, cx) == Mode::Timetable
        });
        assert_eq!(
            view.read_with(cx, |v, _| (
                v.model.as_ref().map(|m| m.timetable_news()),
                v.settings.timetable_seen_of(&v.yard),
            )),
            (Some(0), Some(22))
        );
        // One of the person's, closed: the badge again.
        to_chat(&view, cx);
        yard.emit(r#"{"seq": 23, "kind": "closed", "actor": "yardmaster", "bead": "yd-barn", "data": {"reason": "merged", "originator": "jo"}}"#);
        wait(cx, "the timetable's badge again", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.timetable_news() == 1)
            })
        });
    }

    /// While the yard is away the rail carries no badge on the
